#include <vector>
#include <string>
#include <cstddef>
#include <algorithm>
#include <omp.h>

struct Book {
   std::string title;
   int pages;
};

size_t findLastShortBook(std::vector<Book> const& books) {
    const std::size_t n = books.size();
    if (n == 0) return n; // not found

    // Each thread finds its best (largest) index locally, then we reduce via max.
    // Use a signed type for the reduction identity (-1).
    long long globalBest = -1;

#pragma omp parallel
    {
        long long localBest = -1;

#pragma omp for nowait
        for (long long i = 0; i < static_cast<long long>(n); ++i) {
            if (books[static_cast<std::size_t>(i)].pages < 100) {
                if (i > localBest) localBest = i;
            }
        }

#pragma omp critical
        {
            if (localBest > globalBest) globalBest = localBest;
        }
    }

    if (globalBest < 0) return n; // not found
    return static_cast<std::size_t>(globalBest);
}
